@using sv_90b1466ef1ca41a8a3e8a3556f96c7b3.Services

<div class="settings-section">
    <h3>Appearance</h3>

    @if (StatusMessage is not null)
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @StatusMessage
            <button type="button" class="btn-close" @onclick="() => StatusMessage = null"></button>
        </div>
    }

    <!-- Theme -->
    <div class="mb-3">
        <label class="form-label fw-bold">Theme</label>
        <div>
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="theme"
                           id="@($"theme-{theme}")" value="@theme"
                           checked="@(SelectedTheme == theme)"
                           @onchange="() => SelectedTheme = theme" />
                    <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                </div>
            }
        </div>
    </div>

    <!-- Font Size -->
    <div class="mb-3">
        <label class="form-label fw-bold">Font Size</label>
        <div>
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="fontSize"
                           id="@($"fs-{size}")" value="@size"
                           checked="@(SelectedFontSize == size)"
                           @onchange="() => SelectedFontSize = size" />
                    <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                </div>
            }
        </div>
    </div>

    <!-- Language -->
    <div class="mb-3">
        <label class="form-label fw-bold">Language</label>
        <select class="form-select" @bind="SelectedLanguage">
            <option value="English">English</option>
            <option value="Spanish">Spanish</option>
            <option value="French">French</option>
            <option value="German">German</option>
            <option value="Japanese">Japanese</option>
        </select>
    </div>

    <!-- Compact Mode -->
    <div class="mb-3">
        <div class="form-check form-switch">
            <input class="form-check-input" type="checkbox" id="compactMode" @bind="CompactMode" />
            <label class="form-check-label" for="compactMode">Compact Mode</label>
        </div>
    </div>

    <!-- Live Preview -->
    <div class="mb-3">
        <label class="form-label fw-bold">Preview</label>
        <div class="appearance-preview @GetPreviewClasses()" style="@GetPreviewStyles()">
            <h5>Sample Heading</h5>
            <p>This is a preview of how your content will look with the selected settings.</p>
            <button class="btn btn-sm btn-primary">Sample Button</button>
        </div>
    </div>

    <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string SelectedTheme = "Light";
    private string SelectedFontSize = "Medium";
    private string SelectedLanguage = "English";
    private bool CompactMode;
    private string? StatusMessage;
    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            SelectedTheme = Settings.Theme;
            SelectedFontSize = Settings.FontSize;
            SelectedLanguage = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        if (SelectedTheme == "Dark") classes.Add("preview-dark");
        if (CompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private string GetPreviewStyles()
    {
        var fontSize = SelectedFontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.2rem",
            _ => "1rem"
        };
        return $"font-size:{fontSize};";
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(SelectedTheme, SelectedFontSize, SelectedLanguage, CompactMode);
        await OnSave.InvokeAsync(updated);
        StatusMessage = "Appearance settings saved!";
    }
}
